insert into public.info_articles (id, category, title, summary, body, body_blocks, icon, thumbnail, source, source_url, source_date, published_at, status, placement, region, apply_end_at, child_ages) values
  ('00000000-0000-4000-8000-000000006931', 'subsidy'::info_category, '우리 집이 받을 수 있는 지원금, 어디서 찾을까요?', '흩어져 있는 생활 지원 정보, 보조금24에서 확인하는 순서를 정리했어요.', array['흩어져 있는 생활 지원 정보, 보조금24에서 확인하는 순서를 정리했어요.', '내 생활에 맞게 하나씩 확인해요', '가장 먼저 지금의 상황과 필요한 정보를 적어보세요. 공식 안내의 기준일과 적용 대상을 확인하고, 궁금한 부분은 담당 기관의 안내를 참고하세요.', '오늘 해볼 수 있는 작은 실천', '이번 주에 확인할 항목 한 가지를 정하고 메모에 남겨보세요. 이 글을 저장해 두면 마이페이지에서 다시 읽을 수 있어요.']::text[], '[{"type":"paragraph","text":"흩어져 있는 생활 지원 정보, 보조금24에서 확인하는 순서를 정리했어요."},{"type":"heading","text":"내 생활에 맞게 하나씩 확인해요"},{"type":"paragraph","text":"가장 먼저 지금의 상황과 필요한 정보를 적어보세요. 공식 안내의 기준일과 적용 대상을 확인하고, 궁금한 부분은 담당 기관의 안내를 참고하세요."},{"type":"heading","text":"오늘 해볼 수 있는 작은 실천"},{"type":"paragraph","text":"이번 주에 확인할 항목 한 가지를 정하고 메모에 남겨보세요. 이 글을 저장해 두면 마이페이지에서 다시 읽을 수 있어요."}]'::jsonb, 'landmark', '', '주부테크 편집팀 · 화면 검토용 예시', '', '2026-10-21', '2026-10-21T09:00:00+09:00', 'published', 'featured', '성남시', '2026-10-27T23:59:00+09:00', '{}'::text[]),
