  ('00000000-0000-4000-8000-000000007231', '00000000-0000-4000-8000-000000006135', 'https://example.com/demo-review', '향이 강하지 않아 설거지할 때 쓰기 좋았어요.', 5, '{"passed":false,"items":[{"key":"chars","ok":false,"required":800,"actual":25,"message":"글자 수가 775자 더 필요해요"},{"key":"photos","ok":true,"required":5,"actual":5,"message":"사진 5장 확인"},{"key":"keywords","ok":false,"required":["맑은생활"],"actual":[],"message":"''맑은생활'' 키워드를 넣어 주세요"},{"key":"hashtags","ok":false,"required":["주부테크","협찬"],"actual":[],"message":"#주부테크 #협찬 해시태그가 필요해요"},{"key":"link","ok":true,"required":"열리는 링크","actual":"HTTP 200","message":"링크 확인"}],"checkedAt":"2026-10-20T12:00:00+09:00"}'::jsonb, 'pending'::review_status, null, null, '2026-10-20T12:00:00+09:00', null, null),
