insert into public.posts (id, board, topic, author_id, title, body, status, moderation_note, source_journal_id, created_at) values
  ('00000000-0000-4000-8000-000000007031', 'sidejob'::board_key, '부업후기', '00000000-0000-4000-8000-000000006d31', '등원 후 두 시간, 나만의 작은 루틴이 생겼어요', '처음에는 시간을 어떻게 써야 할지 막막했어요. 이제는 관심 있는 체험을 살펴보고 하루의 기록을 남기고 있어요. 작은 일도 꾸준히 해보려고요.', 'published', null, null, '2026-10-20T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007032', 'stock'::board_key, '주식·재테크', '00000000-0000-4000-8000-000000006d33', '매매일지를 쓰고 달라진 건 수익보다 마음이었어요', '종목을 고른 이유를 적으니, 나중에 내 판단을 차분히 돌아볼 수 있었어요. 오늘도 결과보다 과정을 기록해 봅니다.', 'published', null, null, '2026-10-19T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007033', 'groupbuy'::board_key, '공구/쇼핑', '00000000-0000-4000-8000-000000006d32', '장보기 전에 냉장고 사진 한 장 찍어보세요', '이미 있는 재료를 또 사는 일이 줄었어요. 생각보다 도움이 되는 작은 습관이에요.', 'published', null, null, '2026-10-18T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007034', 'income'::board_key, '수익인증', '00000000-0000-4000-8000-000000006d32', '체험단 후기 세 건 올리고 이번 달 3천 원 모았어요', '큰돈은 아니지만 아이 간식값은 나왔어요. 제품도 받아서 생활비가 조금 줄었고요. 예시 글이에요.', 'published', null, null, '2026-10-17T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007035', 'subsidy'::board_key, '지원금제보', '00000000-0000-4000-8000-000000006d33', '아이돌봄 지원 신청 기간, 공식 안내에서 먼저 확인하세요', '지역마다 기간이 달라서 저는 지난번에 놓쳤어요. 공식 안내를 먼저 보고 신청 서류를 챙기면 편해요.', 'published', null, null, '2026-10-16T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007036', 'free'::board_key, '자유', '00000000-0000-4000-8000-000000006d31', '오늘 하원 전까지 뭐 하세요?', '다들 등원 후 시간을 어떻게 쓰시는지 궁금해요. 저는 후기 사진을 정리하고 있어요.', 'published', null, null, '2026-10-15T10:00:00+09:00'),
  ('00000000-0000-4000-8000-000000007037', 'sidejob'::board_key, '부업후기', '00000000-0000-4000-8000-000000006d32', '재택 부업 시작 전에 정산 조건을 꼭 물어보세요', '처음 했던 곳은 정산일이 늦어서 고생했어요. 업무 범위와 정산일을 먼저 확인하는 습관이 생겼어요.', 'published', null, null, '2026-10-14T10:00:00+09:00');
